import React, { useEffect, useState } from "react";
import axios from "axios";
import ProductCard from "./ProductCard";
import { useLocation, useNavigate } from "react-router-dom";
import "./global.css";

export default function Home() {
  const [products, setProducts] = useState([]);
  const location = useLocation();
  const navigate = useNavigate();

  // product user originally chose → wants to swap
  const swapFor = location.state?.swapFor || null;

  useEffect(() => {
    axios
      .get("http://localhost:5001/api/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.log(err));
  }, []);

  const handleSwapSelection = async (selectedProduct) => {
    if (!swapFor) return;

    const user = JSON.parse(localStorage.getItem("user") || "null");

    if (!user) {
      alert("Please login to send a swap request");
      navigate("/login");
      return;
    }

    // price difference validation
    const diff = Math.abs(Number(swapFor.price) - Number(selectedProduct.price));
    if (diff > 200) {
      alert(`Swap Failed ❌ Price difference ₹${diff} is more than ₹200`);
      return;
    }

    try {
      const res = await axios.post("http://localhost:5001/api/swaps/create", {
        offeredProductId: selectedProduct._id,
        productWantedId: swapFor._id,
        requestedById: user._id,
      });

      if (res.data.success) {
        // redirect to thank you page
        navigate("/thankyou", {
          state: {
            product: selectedProduct,
            method: "Swap Request Sent",
          },
        });
      } else {
        alert(res.data.error || "Swap failed");
      }
    } catch (err) {
      alert(err.response?.data?.error || "Swap request failed");
    }
  };

  const handleClick = (p) => {
    if (swapFor) {
      handleSwapSelection(p);
    } else {
      navigate(`/product/${p._id}`);
    }
  };

  return (
    <div className="home-page">
      <div className="hero-section">
        <h1>Welcome to Rewear</h1>
        <p className="tagline">Buy • Sell • Swap — Sustainable Fashion</p>
      </div>

      <div className="action-bar">
        <button className="action-btn" onClick={() => navigate("/")}>
          Buy / Swap
        </button>

        <button className="action-btn" onClick={() => navigate("/create")}>
          Sell
        </button>
      </div>

      {swapFor ? (
        <h2 className="section-title">
          Select product to swap with <strong>{swapFor.title}</strong>
        </h2>
      ) : (
        <h2 className="section-title">Available Products</h2>
      )}

      <div className="product-grid">
        {products.map((p) => (
          <div key={p._id} onClick={() => handleClick(p)}>
            <ProductCard product={p} />
          </div>
        ))}
      </div>
    </div>
  );
}
